 record_no integer NOT NULL,
 missing text[] NOT NULL,
 null_groups text[] NOT NULL,
 PRIMARY KEY(resource_id,record_no),
 CHECK(record_no=0)
);

CREATE TABLE IF NOT EXISTS statarena_app.cat_supp_fixtures_rows (
 resource_id bigint NOT NULL REFERENCES statarena_app.catalog_editions ON DELETE CASCADE,
 record_no integer NOT NULL,
 missing text[] NOT NULL,
 null_groups text[] NOT NULL,
 parent_no integer NOT NULL,
 position integer NOT NULL,
 "away" text,
 "date" text,
 "gw" text,
 "home" text,
 "time" text,
 PRIMARY KEY(resource_id,record_no),
 FOREIGN KEY(resource_id,parent_no) REFERENCES statarena_app.cat_supp_fixtures(resource_id,record_no) ON DELETE CASCADE,
 UNIQUE(resource_id,parent_no,position)
);

CREATE OR REPLACE FUNCTION statarena_app.read_cat_supp_fixtures_rows(r statarena_app.cat_supp_fixtures_rows) RETURNS jsonb LANGUAGE sql STABLE AS $$ SELECT (jsonb_build_object('away', r."away",
'date', r."date",
'gw', r."gw",
'home', r."home",
'time', r."time") - r.missing); $$;

CREATE OR REPLACE FUNCTION statarena_app.read_cat_supp_fixtures(r statarena_app.cat_supp_fixtures) RETURNS jsonb LANGUAGE sql STABLE AS $$ SELECT (jsonb_build_object('rows', CASE WHEN 'rows'=ANY(r.null_groups) THEN NULL ELSE (SELECT coalesce(jsonb_agg((jsonb_build_object('away', r1."away",
'date', r1."date",
'gw', r1."gw",
'home', r1."home",
'time', r1."time") - r1.missing) ORDER BY r1.position), '[]'::jsonb) FROM statarena_app.cat_supp_fixtures_rows r1
 WHERE r1.resource_id=r.resource_id AND r1.parent_no=r.record_no) END) - r.missing); $$;

