 "meta_terms" text,
 "meta_usage" text,
 PRIMARY KEY(resource_id,record_no),
 CHECK(record_no=0)
);

CREATE TABLE IF NOT EXISTS statarena_app.cat_supp_index_competitions (
 resource_id bigint NOT NULL REFERENCES statarena_app.catalog_editions ON DELETE CASCADE,
 record_no integer NOT NULL,
 missing text[] NOT NULL,
 null_groups text[] NOT NULL,
 parent_no integer NOT NULL,
 position integer NOT NULL,
 "country_code" text,
 "folder" text,
 "name" text,
 "season" text,
 "tables_fixtures_path" text,
 "tables_fixtures_rows" integer,
 "tables_fixtures_sha256" text,
 "tables_goals_path" text,
 "tables_goals_rows" integer,
 "tables_goals_sha256" text,
 "tables_results_path" text,
 "tables_results_rows" integer,
 "tables_results_sha256" text,
 PRIMARY KEY(resource_id,record_no),
 FOREIGN KEY(resource_id,parent_no) REFERENCES statarena_app.cat_supp_index(resource_id,record_no) ON DELETE CASCADE,
 UNIQUE(resource_id,parent_no,position)
);

CREATE OR REPLACE FUNCTION statarena_app.read_cat_supp_index_competitions(r statarena_app.cat_supp_index_competitions) RETURNS jsonb LANGUAGE sql STABLE AS $$ SELECT (jsonb_build_object('country_code', r."country_code",
'folder', r."folder",
'name', r."name",
'season', r."season",
'tables', CASE WHEN 'tables'=ANY(r.null_groups) THEN NULL ELSE (jsonb_build_object('fixtures', CASE WHEN 'tables.fixtures'=ANY(r.null_groups) THEN NULL ELSE (jsonb_build_object('path', r."tables_fixtures_path",
'rows', r."tables_fixtures_rows",
'sha256', r."tables_fixtures_sha256") - array_remove(ARRAY[CASE WHEN 'tables.fixtures.path'=ANY(r.missing) THEN 'path' END, CASE WHEN 'tables.fixtures.rows'=ANY(r.missing) THEN 'rows' END, CASE WHEN 'tables.fixtures.sha256'=ANY(r.missing) THEN 'sha256' END],NULL)) END,
'goals', CASE WHEN 'tables.goals'=ANY(r.null_groups) THEN NULL ELSE (jsonb_build_object('path', r."tables_goals_path",
'rows', r."tables_goals_rows",
'sha256', r."tables_goals_sha256") - array_remove(ARRAY[CASE WHEN 'tables.goals.path'=ANY(r.missing) THEN 'path' END, CASE WHEN 'tables.goals.rows'=ANY(r.missing) THEN 'rows' END, CASE WHEN 'tables.goals.sha256'=ANY(r.missing) THEN 'sha256' END],NULL)) END,
'results', CASE WHEN 'tables.results'=ANY(r.null_groups) THEN NULL ELSE (jsonb_build_object('path', r."tables_results_path",
'rows', r."tables_results_rows",
'sha256', r."tables_results_sha256") - array_remove(ARRAY[CASE WHEN 'tables.results.path'=ANY(r.missing) THEN 'path' END, CASE WHEN 'tables.results.rows'=ANY(r.missing) THEN 'rows' END, CASE WHEN 'tables.results.sha256'=ANY(r.missing) THEN 'sha256' END],NULL)) END) - array_remove(ARRAY[CASE WHEN 'tables.fixtures'=ANY(r.missing) THEN 'fixtures' END, CASE WHEN 'tables.goals'=ANY(r.missing) THEN 'goals' END, CASE WHEN 'tables.results'=ANY(r.missing) THEN 'results' END],NULL)) END) - r.missing); $$;

CREATE OR REPLACE FUNCTION statarena_app.read_cat_supp_index(r statarena_app.cat_supp_index) RETURNS jsonb LANGUAGE sql STABLE AS $$ SELECT (jsonb_build_object('competitions', CASE WHEN 'competitions'=ANY(r.null_groups) THEN NULL ELSE (SELECT coalesce(jsonb_agg((jsonb_build_object('country_code', r1."country_code",
'folder', r1."folder",
'name', r1."name",
'season', r1."season",
'tables', CASE WHEN 'tables'=ANY(r1.null_groups) THEN NULL ELSE (jsonb_build_object('fixtures', CASE WHEN 'tables.fixtures'=ANY(r1.null_groups) THEN NULL ELSE (jsonb_build_object('path', r1."tables_fixtures_path",
'rows', r1."tables_fixtures_rows",
'sha256', r1."tables_fixtures_sha256") - array_remove(ARRAY[CASE WHEN 'tables.fixtures.path'=ANY(r1.missing) THEN 'path' END, CASE WHEN 'tables.fixtures.rows'=ANY(r1.missing) THEN 'rows' END, CASE WHEN 'tables.fixtures.sha256'=ANY(r1.missing) THEN 'sha256' END],NULL)) END,
'goals', CASE WHEN 'tables.goals'=ANY(r1.null_groups) THEN NULL ELSE (jsonb_build_object('path', r1."tables_goals_path",
'rows', r1."tables_goals_rows",
'sha256', r1."tables_goals_sha256") - array_remove(ARRAY[CASE WHEN 'tables.goals.path'=ANY(r1.missing) THEN 'path' END, CASE WHEN 'tables.goals.rows'=ANY(r1.missing) THEN 'rows' END, CASE WHEN 'tables.goals.sha256'=ANY(r1.missing) THEN 'sha256' END],NULL)) END,
'results', CASE WHEN 'tables.results'=ANY(r1.null_groups) THEN NULL ELSE (jsonb_build_object('path', r1."tables_results_path",
'rows', r1."tables_results_rows",
'sha256', r1."tables_results_sha256") - array_remove(ARRAY[CASE WHEN 'tables.results.path'=ANY(r1.missing) THEN 'path' END, CASE WHEN 'tables.results.rows'=ANY(r1.missing) THEN 'rows' END, CASE WHEN 'tables.results.sha256'=ANY(r1.missing) THEN 'sha256' END],NULL)) END) - array_remove(ARRAY[CASE WHEN 'tables.fixtures'=ANY(r1.missing) THEN 'fixtures' END, CASE WHEN 'tables.goals'=ANY(r1.missing) THEN 'goals' END, CASE WHEN 'tables.results'=ANY(r1.missing) THEN 'results' END],NULL)) END) - r1.missing) ORDER BY r1.position), '[]'::jsonb) FROM statarena_app.cat_supp_index_competitions r1
 WHERE r1.resource_id=r.resource_id AND r1.parent_no=r.record_no) END,
'meta', CASE WHEN 'meta'=ANY(r.null_groups) THEN NULL ELSE (jsonb_build_object('retrieved_at_utc', r."meta_retrieved_at_utc",
'source', r."meta_source",
'source_generated_at_utc', r."meta_source_generated_at_utc",
'terms', r."meta_terms",
'usage', r."meta_usage") - array_remove(ARRAY[CASE WHEN 'meta.retrieved_at_utc'=ANY(r.missing) THEN 'retrieved_at_utc' END, CASE WHEN 'meta.source'=ANY(r.missing) THEN 'source' END, CASE WHEN 'meta.source_generated_at_utc'=ANY(r.missing) THEN 'source_generated_at_utc' END, CASE WHEN 'meta.terms'=ANY(r.missing) THEN 'terms' END, CASE WHEN 'meta.usage'=ANY(r.missing) THEN 'usage' END],NULL)) END) - r.missing); $$;

